const BANNER =
  "// AUTO-GENERATED by scaffold.mjs — do not edit. Managed by forge.config.yaml.\n";

// `feature.yaml` `contributes.*.import` paths are written relative to `src/`,
// without a leading `./` (e.g. `features/theming/ThemeProvider`). Each
// generated aggregator file lives at a different depth under `src/`, so the
// path must be re-based from `src/` to that aggregator's own directory
// before it can resolve at build time.
function resolveImport(featureImport, prefix) {
  const relative = featureImport.replace(/^\.?\/+/, "");
  return `${prefix}${relative}`;
}

function importName(component, id, kind) {
  return `${component}_${id}_${kind}`;
}

function buildRoutes(features) {
  // src/app/routes.generated.tsx is one level under src/.
  const prefix = "../";
  const items = features.flatMap((f) =>
    f.contributes.routes.map((r) => ({ ...r, alias: importName(r.component, f.id, "route") })),
  );
  const imports = items
    .map((r) => `import { ${r.component} as ${r.alias} } from "${resolveImport(r.import, prefix)}";`)
    .join("\n");
  const entries = items
    .map((r) => `  { path: "${r.path}", element: <${r.alias} /> },`)
    .join("\n");
  return `${BANNER}import type { RouteObject } from "react-router-dom";
${imports}

export const featureRoutes: RouteObject[] = [
${entries}
];
`;
}

function buildNav(features) {
  const entries = features
    .flatMap((f) => f.contributes.nav)
    .map((n) => `  { label: "${n.label}", to: "${n.to}" },`)
    .join("\n");
  return `${BANNER}export type NavItem = { label: string; to: string };

export const featureNav: NavItem[] = [
${entries}
];
`;
}

function buildProviders(features) {
  // src/app/providers.generated.tsx is one level under src/.
  const prefix = "../";
  // Providers carry an optional numeric `priority` (default 0). LOWER priority
  // is emitted FIRST → becomes the OUTERMOST wrapper. This lets a feature like
  // notifications' ErrorBoundary sit outside every other provider so it can
  // catch errors thrown by its siblings. Ties break on feature id, then the
  // provider's original order within its feature — keeping output deterministic.
  const items = features
    .flatMap((f) =>
      f.contributes.providers.map((p, order) => ({
        ...p,
        alias: importName(p.component, f.id, "provider"),
        priority: typeof p.priority === "number" ? p.priority : 0,
        featureId: f.id,
        order,
      })),
    )
    .sort(
      (a, b) =>
        a.priority - b.priority ||
        a.featureId.localeCompare(b.featureId) ||
        a.order - b.order,
    );
  const imports = items
    .map((p) => `import { ${p.component} as ${p.alias} } from "${resolveImport(p.import, prefix)}";`)
    .join("\n");
  const open = items.map((p) => `<${p.alias}>`).join("");
  const close = items.map((p) => `</${p.alias}>`).reverse().join("");
  return `${BANNER}import type { ReactNode } from "react";
${imports}

export function FeatureProviders({ children }: { children: ReactNode }) {
  return ${open || "<>"}{children}${close || "</>"};
}
`;
}

function buildHttpHooks(features) {
  // src/api/http/hooks.generated.ts is two levels under src/.
  const prefix = "../../";
  const handlers = features.flatMap((f) => f.contributes.http);
  const imports = handlers
    .map((h, i) => {
      const path = Object.values(h)[0];
      return `import { ${path.split("/").pop()} as h${i} } from "${resolveImport(path, prefix)}";`;
    })
    .join("\n");
  const list = handlers.map((_, i) => `h${i}`).join(", ");
  return `${BANNER}${imports}

export const responseErrorHandlers = [${list}];
`;
}

export function buildAggregators(enabledFeatures) {
  const f = [...enabledFeatures].sort((a, b) => a.id.localeCompare(b.id));
  return {
    "src/app/routes.generated.tsx": buildRoutes(f),
    "src/app/nav.generated.ts": buildNav(f),
    "src/app/providers.generated.tsx": buildProviders(f),
    "src/api/http/hooks.generated.ts": buildHttpHooks(f),
  };
}
